function validate([nums, index]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (index.length !== nums.length) return 'nums and index must have the same length.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each value in nums is between 0 and 100.';
  if (index.some((v, i) => !Number.isInteger(v) || v < 0 || v > i)) return 'Each index[i] is between 0 and i.';
  return null;
}

