function createTargetArray(nums, index) {
  const target = [];
  for (let i = 0; i < nums.length; i++) {
    let position = target.length;
    while (position > index[i]) {
      target[position] = target[position - 1];
      position--;
    }
    target[index[i]] = nums[i];
  }
  return target;
}

