function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  const maxValue = rand() < 0.4 ? 5 : 100;
  const style = rand();
  const nums = [];
  const index = [];
  for (let i = 0; i < n; i++) {
    nums.push(Math.floor(rand() * (maxValue + 1)));
    // Mostly random slots, sometimes always the front or always the end.
    const roll = rand();
    if (style < 0.15 || (style < 0.5 && roll < 0.3)) index.push(0);
    else if (style < 0.3 || (style < 0.5 && roll < 0.6)) index.push(i);
    else index.push(Math.floor(rand() * (i + 1)));
  }
  return [nums, index];
}
